add("4","morgan2024cs3","Morgan (The Next Platform)",2024,"Cerebras goes hyperscale with third-gen waferscale supercomputers (March 14, 2024)",None,"https://www.nextplatform.com/ai/2024/03/14/cerebras-goes-hyperscale-with-third-gen-waferscale-supercomputers/1642584","Press, secondary source. The 8-wide FP16 SIMD of WSE-3 (4-wide before), the sparse qualifier on the 256-exaflop cluster figure, MemoryX tiers from 24 TB to 1,200 TB, and CG-1 at $100M for 32 nodes. Slides 13 and 14.")
add("4","cerebras2024cg3","Cerebras Systems",2024,"Cerebras and G42 announce Condor Galaxy 3 (March 13, 2024)",None,"https://cerebras.ai/press-release/cerebras-g42-announce-condor-galaxy-3","Vendor press release. CG-3 in Dallas with 64 CS-3 at 8 'AI exaflops'; with CG-1 and CG-2 the network totals 16; the Condor Galaxy table. Slide 14.")
add("4","cerebras2024s1","Cerebras Systems (SEC Form S-1)",2024,"Form S-1 registration statement (filed September 30, 2024)",None,"https://www.sec.gov/Archives/edgar/data/2021728/000162828024041596/cerebras-sx1.htm","Filing (SEC). Revenue of $24.6M (2022), $78.7M (2023) and $136.4M (H1 2024); G42 was 83 percent of 2023 revenue and 87 percent of H1 2024 revenue. Slides 14 and 15.")
add("4","cerebras2024inference","Cerebras Systems",2024,"Introducing Cerebras Inference: AI at instant speed (August 27, 2024)",None,"https://cerebras.ai/blog/introducing-cerebras-inference-ai-at-instant-speed","Vendor blog. The launch: Llama 3.1 8B at 1,800 tokens/s and 70B at 450 tokens/s with 16-bit weights, claimed 20 times GPU clouds; the first bar of the speed chart. Slides 15 and 33.")
add("4","cerebras2024triples","Cerebras Systems",2024,"Cerebras triples its industry-leading inference performance (October 25, 2024)",None,"https://www.cerebras.ai/press-release/cerebras-triples-its-industry-leading-inference-performance-setting-new-all-time-record","Vendor press release. 2,100 tokens/s on the 70B Llama model as measured by Artificial Analysis; the second bar of the speed chart. Slides 15 and 33.")
add("4","futurum2026cerebrass1","Futurum Group",2026,"Cerebras S-1 teardown: is the $23B wafer-scale IPO the end of GPU homogeneity? (April 22, 2026)",None,"https://futurumgroup.com/insights/cerebras-s-1-teardown-is-the-23b-wafer-scale-ipo-the-end-of-gpu-homogeneity/","Analyst note, secondary source. The April 2026 S-1: 2025 revenue $510M, MBZUAI 62 and G42 24 percent (86 together), backlog $24.6B, GAAP profit only from a $363.3M one-time gain, OpenAI terms of 750 MW with an option to 2 GW. Slides 14 and 15.")
