import kit_machinery as K
K.P, K.SECTIONS, K.TITLE, K.ZIPBASE = P, SECTIONS, TITLE, ZIPBASE

if __name__ == "__main__":
    base = os.path.dirname(os.path.abspath(__file__))
    keys=[p['key'] for p in P]; assert len(keys)==len(set(keys)), "duplicate keys"
    outdir = os.path.join(base, "papers_kit"); os.makedirs(outdir, exist_ok=True)
    open(os.path.join(outdir, "reading_list.csv"), "w").write(K.gen_csv())
    open(os.path.join(outdir, "reading_list.bib"), "w").write(K.gen_bib())
    open(os.path.join(outdir, "fetch_papers.sh"), "w").write(K.gen_script())
    open(os.path.join(outdir, "README.md"), "w").write(K.gen_readme())
    open(os.path.join(outdir, "reading_list_appendix.tex"), "w").write(K.gen_appendix())
    print(len(P), "entries;", sum(1 for p in P if p['arxiv']), "on arXiv;", sum(1 for p in P if not p['arxiv'] and p['url'] and p['url'].lower().endswith('.pdf')), "direct PDFs")
